"""Preserve failed 16-control experiment; add personally reviewed Sam fork."""
from pathlib import Path
import json,copy,hashlib,datetime
D=Path(__file__).resolve().parent
if (D/'final-freeze.json').exists(): raise SystemExit('Frozen evidence already exists; preserve it and start a new experiment directory.')
h=lambda p:hashlib.file_digest(p.open('rb'),'sha256').hexdigest()
w=lambda n,v:(D/n).write_text(json.dumps(v,indent=2)+'\n')
fit=json.loads((D/'repaired-fit.json').read_text());validation=json.loads((D/'validation.json').read_text());point=copy.deepcopy(next(p for p in validation['points'] if p['id']=='F02'));point['id']='C18';point['role']='control';point['status']='Promoted after failed 16-control validation; source and modern coordinates unchanged; no longer independent.';point['promotion']={'old_point':next(p for p in validation['points'] if p['id']=='F02'),'old_fit_sha256':h(D/'repaired-fit.json'),'old_result':next(p for p in json.loads((D/'validation-scores.json').read_text())['points'] if p['id']=='F02'),'baseline_result':next(p for p in json.loads((D/'baseline-validation-scores.json').read_text())['points'] if p['id']=='F02'),'reason':'Shared northern main stem, two successive eastern marsh branches and lower Sam confluence establish identity. Previous raster displaces this entire Sam reach. New control supplies physical support between northern Baddeck and existing eastern controls.'};fit['points'].append(point);fit['status']='Provisional 17-control TPS; Sam fork repair; preserve 14- and 16-control experiments and all failed checks.'
w('final-fit.json',fit);w('final-freeze.json',{'at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'fit_sha256':h(D/'final-fit.json'),'previous_fit_sha256':h(D/'repaired-fit.json'),'boundary_sha256':h(D.parent/'boundary.json'),'control_count':17,'new_validation_collected':False,'criteria':{'median_ground_m_max':100,'worst_ground_m_max':200,'whole_raster_and_seams_required':True}})
d=json.loads((D/'repair-diagnostic.json').read_text());d['points']+= [p for p in validation['points'] if p['id']!='F02'];d.update(fit_sha256=h(D/'final-fit.json'),status='Reused diagnostics; F02 has been promoted with exact old scores retained, so is excluded. No fresh independent validation claim.');w('final-diagnostic.json',d)
